    resp = apis.phone.search_text_messages(access_token=phone_token, phone_number=christopher_phone, query='', only_latest_per_contact=False, page_index=page_index, page_limit=20)
    # normalize response
    if isinstance(resp, list):
        msgs=resp
    elif isinstance(resp, dict) and 'success' in resp:
        msgs=resp['success']
    elif isinstance(resp, dict) and 'results' in resp:
        msgs=resp['results']
    else:
        msgs=resp.get('success', []) if isinstance(resp, dict) else []
    print('page', page_index, 'count', len(msgs))
    for m in msgs:
        all_msgs.append(m)
    if not msgs:
        break
    page_index += 1

print('total messages', len(all_msgs))
# sort by sent_at if possible
from datetime import datetime

def parse_dt(s):
    try:
        return datetime.fromisoformat(s.replace('Z','+00:00'))
    except Exception:
        return None

all_msgs_sorted = sorted(all_msgs, key=lambda x: parse_dt(x.get('sent_at','')) or datetime.min)
